import{z as A,x as l,o as B,c as d,q as n,j as r,D as a,d as e,s as t,S as o,b as i}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"微观结构噪声的实证","description":"","frontmatter":{"title":"微观结构噪声的实证","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hfs-micro-noise-empirics.md","filePath":"quant/hfs-micro-noise-empirics.md","lastUpdated":1791063341000}'),p={name:"quant/hfs-micro-noise-empirics.md"};function m(c,E,u,h,D,_){const s=l("Mermaid");return B(),d("div",null,[E[2]||(E[2]=n('<h1 id="微观结构噪声的实证" tabindex="-1">微观结构噪声的实证 <a class="header-anchor" href="#微观结构噪声的实证" aria-label="Permalink to &quot;微观结构噪声的实证&quot;">​</a></h1><div class="epigraph"><p>噪声不是恒定背景，它有自己的行情：随波动起落、随价差与制度切换；把它当对象测量，既是市场质量的读数，也是一切修正估计量的输入。</p><footer>—— 据 Hansen and Lunde, Journal of Business and Economic Statistics, 2006；Bandi and Russell, 同刊 2006 整理</footer></div><p><a href="/quant/hfs-highfreq-beta">上一课</a>把相对读数合成完毕，估计侧的工具链到此齐全；应用单元从测量「自己的敌人」开始。机制在<a href="/quant/microstructure-noise">微观结构噪声</a>写过，签名图斜率在<a href="/quant/noise-variance-estimate">噪声方差估计</a>写过；本课写实证口径：噪声的量级怎么报、结构怎么判、横截面与时间上哪些规律是稳的，以及这些规律如何反过来约束前几课的调参。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>要测的是噪声方差 \\(\\sigma_\\varepsilon^2\\)，或更有用的噪声-信号比 \\(\\sigma_\\varepsilon^2/IV\\)。可用口径有四条：签名图高频端的斜率；两尺度估计的残差项；相邻收益的 Roll 反转；把噪声写进似然的 QMLE（Aït-Sahalia、Mykland 与 Zhang，RFS 2005）。四条口径在 i.i.d. 弹跳的世界里应当一致，实证上常常不一致——不一致本身就是信息：它说明噪声有结构。Hansen 与 Lunde（JBES 2006）对道琼斯成分股的系统研究给出两个稳的结论：噪声方差与当日波动率强相关，且远非常数；Bandi 与 Russell（同刊 2006）进一步说明最优采样频率随标的流动性移动。缺口是把「有噪声」升级成「噪声有多少、什么结构」，给下游的带宽、采样上限与市场质量监控供数。</p><p><span class="marginnote">术语翻译：「签名图」就是把按不同格距算出的已实现方差对格距画一张图。没有噪声时它是平线；格距越密越往上翘，高频端翘起的斜率就是噪声方差在报数——一张图同时给了信号与杂音的读数。</span></p><p><span class="marginnote">Roll 弹跳口径把有效价差读成 \\(2\\sigma_\\varepsilon\\)：签名图斜率与 Roll 反转估出的 \\(\\sigma_\\varepsilon\\) 若差一倍，先怀疑清洗不干净，再怀疑噪声有结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实证流程四步。<strong>先清洗后测量</strong>：坏 tick、错价、重复报告都会伪装成噪声，把 \\(\\sigma_\\varepsilon^2\\) 抬高数倍——清洗规则属于上游的数据契约，这里只钉顺序。<strong>多口径并报</strong>：签名图斜率、两尺度残差、Roll 反转一起报；口径间一致则接近 i.i.d.，系统性分歧则写明方向（序列相关、与价格相关）。<strong>按日估计、按时序看</strong>：噪声方差是日度序列，与当日 \\(IV\\)、价差、成交量并排画，相关结构一眼可见；跨年平均会抹掉带宽最需要的信息。<strong>横截面分层</strong>：按流动性、tick 大小分层报告噪声-信号比，采样上限的分层规则从这里出。</p>',9)),(B(),r(o,null,{default:a(()=>[t(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%B8%85%E6%B4%97%E5%90%8E%E7%9A%84%E9%80%90%E7%AC%94%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20M%5B%22%E5%9B%9B%E5%8F%A3%E5%BE%84%E6%B5%8B%E9%87%8F%EF%BC%9A%E7%AD%BE%E5%90%8D%E5%9B%BE%E3%80%81%E4%B8%A4%E5%B0%BA%E5%BA%A6%E6%AE%8B%E5%B7%AE%E3%80%81Roll%E3%80%81QMLE%22%5D%0A%20%20M%20--%3E%20S%7B%22%E5%8F%A3%E5%BE%84%E9%97%B4%E4%B8%80%E8%87%B4%EF%BC%9F%22%7D%0A%20%20S%20--%3E%7C%22%E4%B8%80%E8%87%B4%22%7C%20I%5B%22%E8%BF%91%E4%BC%BC%20i.i.d.%EF%BC%9A%E7%9B%B4%E6%8E%A5%E4%BE%9B%E5%B8%A6%E5%AE%BD%E4%B8%8E%E9%87%87%E6%A0%B7%E4%B8%8A%E9%99%90%22%5D%0A%20%20S%20--%3E%7C%22%E5%88%86%E6%AD%A7%22%7C%20ST%5B%22%E5%86%99%E6%98%8E%E7%BB%93%E6%9E%84%EF%BC%9A%E5%BA%8F%E5%88%97%E7%9B%B8%E5%85%B3%E6%88%96%E5%86%85%E7%94%9F%EF%BC%8C%E6%8D%A2%E5%81%87%E8%AE%BE%E6%9C%80%E5%BC%B1%E7%9A%84%E4%BC%B0%E8%AE%A1%E9%87%8F%22%5D%0A%20%20I%20--%3E%20D%5B%22%E6%8C%89%E6%97%A5%E5%BA%8F%E5%88%97%EF%BC%9A%E4%B8%8E%20IV%E3%80%81%E4%BB%B7%E5%B7%AE%E3%80%81%E9%87%8F%E5%B9%B6%E6%8E%92%22%5D%0A%20%20ST%20--%3E%20D%0A%20%20D%20--%3E%20U%5B%22%E8%BE%93%E5%87%BA%EF%BC%9A%E5%99%AA%E5%A3%B0-%E4%BF%A1%E5%8F%B7%E6%AF%94%E5%88%86%E5%B1%82%E3%80%81%E9%87%87%E6%A0%B7%E4%B8%8A%E9%99%90%E3%80%81%E5%B8%82%E5%9C%BA%E8%B4%A8%E9%87%8F%E7%9B%91%E6%8E%A7%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=i("h2",{id:"机制",tabindex:"-1"},[e("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=i("p",null,"噪声为什么有行情：它的来源——弹跳、圆整、存货偏离——全是交易过程的函数。波动大的日子价差宽、存货摆动大，\\(\\sigma_\\varepsilon^2\\) 随 \\(IV\\) 上涨，这是 Hansen–Lunde 的核心发现；tick 调整与市场事件让噪声序列带结构断点。这解释了前几课为什么反复强调调参随日更新：带宽是噪声的泛函，噪声自己是一个随机过程，固定参数等于用平均天气配每一天的衣服。噪声-信号比还是市场质量的相对读数：比值高的标的，价格发现被观测摩擦拖累的比例高，同样名义价差下可读性更差——接回 Hasbrouck 把定价误差方差当市场质量的口径。",-1)),(B(),r(o,null,{default:a(()=>[t(s,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20HI%5B%22%E5%BD%93%E6%97%A5%E6%B3%A2%E5%8A%A8%20IV%20%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20SPR%5B%22%E4%BB%B7%E5%B7%AE%E5%8F%98%E5%AE%BD%22%5D%0A%20%20HI%20--%3E%20INV%5B%22%E5%81%9A%E5%B8%82%E5%AD%98%E8%B4%A7%E6%91%86%E5%8A%A8%E5%8A%A0%E5%A4%A7%22%5D%0A%20%20SPR%20--%3E%20BB%5B%22%E4%B9%B0%E5%8D%96%E5%BC%B9%E8%B7%B3%E5%B9%85%E5%BA%A6%E5%8F%98%E5%A4%A7%22%5D%0A%20%20INV%20--%3E%20DEV%5B%22%E5%AD%98%E8%B4%A7%E5%81%8F%E7%A6%BB%E5%8F%98%E5%A4%A7%22%5D%0A%20%20BB%20--%3E%20NE%5B%22%E5%99%AA%E5%A3%B0%E6%96%B9%E5%B7%AE%20%CF%83%CE%B5%C2%B2%20%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20DEV%20--%3E%20NE%0A%20%20REG%5B%22tick%20%E8%B0%83%E6%95%B4%20%2F%20%E5%B8%82%E5%9C%BA%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20BRK%5B%22%E5%99%AA%E5%A3%B0%E5%BA%8F%E5%88%97%E5%87%BA%E7%8E%B0%E7%BB%93%E6%9E%84%E6%96%AD%E7%82%B9%22%5D%0A%20%20NE%20--%3E%20IMPL%5B%22%E5%B8%A6%E5%AE%BD%E4%B8%8E%E9%87%87%E6%A0%B7%E4%B8%8A%E9%99%90%E5%BF%85%E9%A1%BB%E6%8C%89%E6%97%A5%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">数字实例：日 \\(IV\\approx1\\)（%²）、噪声-信号比 5% 的股票，\\(\\sigma_\\varepsilon^2\\approx0.05\\)；波动翻倍的日子 \\(IV\\approx2\\)，比值若不变，\\(\\sigma_\\varepsilon^2\\) 涨到 0.1——下游带宽的输入跟着翻倍，拿昨天的带宽硬套今天，就是把「平均天气」当成每一天。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>噪声方差不是交易成本：它在价格增量单位上，弹跳假设下才与价差差一个常数倍；报价口径（中点还是成交）一换，读数跟着变，报告必须写口径。i.i.d. 与内生性的检验有限样本功效有限，「未拒绝 i.i.d.」不等于「是 i.i.d.」。噪声实证界定的是已实现统计量的适用域：它不替代执行侧的价差与冲击测量——问成本要在 \\(Y\\) 上问，<a href="/quant/microstructure-noise">微观结构噪声</a>立的那条分界线在本课程全程有效。</p><p><span class="marginnote">常见误区：把测出的噪声方差直接当交易成本写进回测。\\(\\sigma_\\varepsilon\\) 只有在「买卖弹跳」假设成立时才与有效价差差一个常数倍（约 \\(2\\sigma_\\varepsilon\\)），报价口径一换读数就变——真实成本（冲击、滑点）要在执行侧另测，两边不可互相冒充。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>测量对象是 \\(\\sigma_\\varepsilon^2\\) 与噪声-信号比；四口径并报：签名图斜率、两尺度残差、Roll 反转、QMLE。</li><li>口径分歧是信息：指向序列相关或内生噪声，直接改变估计量的选择。</li><li>稳的规律：噪声方差随当日波动上涨、非常数、有制度断点——调参必须随日更新。</li><li>按日估计、分层报告；跨年平均抹掉带宽最需要的信息。</li><li>噪声方差不是价差：问成本在 \\(Y\\) 上问，市场质量用噪声-信号比做相对读数。</li><li>出处：Hansen and Lunde, <em>Realized Variance and Market Microstructure Noise</em>, JBES, 2006；Bandi and Russell, <em>Separating Microstructure Noise from Volatility</em>, JBES, 2006；Aït-Sahalia, Mykland and Zhang, <em>RFS</em>, 2005。</li></ul>',6))])}const C=A(p,[["render",m]]);export{g as __pageData,C as default};
